import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { FaUser, FaEnvelope, FaLock, FaPhone } from 'react-icons/fa';
import logo from '../GI_logo.png';
import './Auth.css';

const Register = () => {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [form, setForm] = useState({
    firstName: '', lastName: '', email: '', password: '', confirmPassword: '', phone: ''
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [error, setError] = useState(null);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setError(null); setMessage(null);
    if (form.password !== form.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: form.firstName,
          lastName: form.lastName,
          email: form.email,
          password: form.password,
          phone: form.phone
        })
      });
      const data = await res.json();
      if (res.ok) {
        setMessage('Registration successful! You can now sign in.');
        setForm({ firstName: '', lastName: '', email: '', password: '', confirmPassword: '', phone: '' });
      } else {
        setError(data.message || 'Registration failed');
      }
    } catch (err) {
      setError('Network error');
    }
    setLoading(false);
  };

  return (
    <div className="auth-bg">
      <div className="auth-container">
        <img src={logo} alt="Global Image Logo" className="auth-logo-img" />
        <h2>Register</h2>
        <div className="auth-tagline">Create your account to get started with Global Image.</div>
        {error && <div style={{color: 'red', marginBottom: '1rem'}}>{error}</div>}
        {message && <div style={{color: 'green', marginBottom: '1rem'}}>{message}</div>}
        <form className="auth-form" onSubmit={handleSubmit}>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaUser /></span>
            <input type="text" id="firstName" name="firstName" placeholder="First Name" required value={form.firstName} onChange={handleChange} />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaUser /></span>
            <input type="text" id="lastName" name="lastName" placeholder="Last Name" required value={form.lastName} onChange={handleChange} />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaEnvelope /></span>
            <input type="email" id="email" name="email" placeholder="Email" required value={form.email} onChange={handleChange} />
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaLock /></span>
            <input type={showPassword ? 'text' : 'password'} id="password" name="password" placeholder="Password" required value={form.password} onChange={handleChange} />
            <button type="button" className="toggle-password" onClick={() => setShowPassword(s => !s)}>{showPassword ? '🙈' : '👁️'}</button>
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaLock /></span>
            <input type={showConfirmPassword ? 'text' : 'password'} id="confirmPassword" name="confirmPassword" placeholder="Confirm Password" required value={form.confirmPassword} onChange={handleChange} />
            <button type="button" className="toggle-password" onClick={() => setShowConfirmPassword(s => !s)}>{showConfirmPassword ? '🙈' : '👁️'}</button>
          </div>
          <div className="auth-input-wrapper">
            <span className="auth-input-icon"><FaPhone /></span>
            <input type="tel" id="phone" name="phone" placeholder="Phone Number" pattern="[0-9]{10,15}" value={form.phone} onChange={handleChange} />
          </div>
          <button type="submit" disabled={loading}>{loading ? 'Registering...' : 'Register'}</button>
        </form>
        <div className="auth-links">
          <Link to="/signin">Already have an account?</Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
